import Image from "next/image";

const skills = [
  ["✦", "UI / UX Design", false],
  ["♡", "Frontend Development", true],
  ["✿", "Brand Storytelling", false],
  ["☁", "Cloud & Systems", true],
  ["✎", "Content Creation", false],
  ["⌁", "Creative Strategy", true],
] as const;

const projects = [
  {
    title: "Bloom Studio",
    label: "Branding · 2025",
    description:
      "A warm, editorial identity for a small creative studio. I shaped the visual language, designed the landing page, and created a gentle content system that feels unmistakably human.",
    image: "https://placehold.co/800x520/f7dce7/8c526b?text=Bloom+Studio",
    tone: "rose",
  },
  {
    title: "Luna Notes",
    label: "Web design · 2024",
    description:
      "A dreamy journaling experience for collecting little thoughts. Soft interaction details, thoughtful typography, and a calm layout make writing feel like a daily ritual.",
    image: "https://placehold.co/800x520/e8e0f5/685b82?text=Luna+Notes",
    tone: "lavender",
  },
] as const;

function SectionHeading({
  number,
  children,
  tone = "rose",
  reversed = false,
}: {
  number: string;
  children: React.ReactNode;
  tone?: "rose" | "lavender";
  reversed?: boolean;
}) {
  return (
    <div className="mb-12 flex items-center gap-4">
      {reversed && <div className={`section-rule-${tone} section-rule-reversed h-px flex-1`} />}
      <h2 className="font-display text-3xl text-ink md:text-4xl">
        <span className={tone === "rose" ? "text-rose" : "text-lavender"}>{number}</span>{" "}
        {children}
      </h2>
      {!reversed && <div className={`section-rule-${tone} h-px flex-1`} />}
    </div>
  );
}

export function Hero() {
  return (
    <section id="hero" className="hero-section relative flex min-h-screen items-center justify-center px-4 pt-20">
      <div className="hero-orbit hero-orbit-one" aria-hidden="true" />
      <div className="hero-orbit hero-orbit-two" aria-hidden="true" />
      <div className="relative z-10 mx-auto max-w-4xl text-center">
        <div className="mb-7 inline-flex items-center gap-2 rounded-full border border-rose/30 bg-white/60 px-4 py-2 text-xs font-semibold uppercase tracking-[0.25em] text-rose">
          <span className="status-dot" /> Available for sweet collaborations
        </div>
        <p className="mb-5 font-hand text-2xl text-lavender">Hello, I&apos;m Fatin ♡</p>
        <h1 className="font-display text-5xl font-semibold leading-[1.05] text-ink md:text-7xl lg:text-8xl">
          Designing little
          <span className="block italic text-rose">moments of magic.</span>
        </h1>
        <p className="mx-auto mt-7 max-w-xl text-base leading-8 text-ink/65 md:text-lg">
          A software engineering student and creative dreamer making thoughtful digital
          experiences with soft edges, clear purpose, and a little bit of sparkle.
        </p>
        <div className="mt-10 flex flex-col justify-center gap-4 sm:flex-row">
          <a href="#projects" className="dream-button dream-button-rose">View my work <span>↗</span></a>
          <a href="#about" className="dream-button dream-button-ghost">A little about me</a>
        </div>
      </div>
      <span className="scroll-note">Scroll to explore ↓</span>
    </section>
  );
}

export function About() {
  return (
    <section id="about" className="relative z-10 px-4 py-24 md:py-32">
      <div className="reveal mx-auto max-w-5xl">
        <SectionHeading number="01." >A little hello</SectionHeading>
        <div className="glass-card overflow-hidden rounded-[2rem] p-7 md:p-12">
          <div className="flex flex-col items-center gap-10 md:flex-row">
            <div className="portrait-frame shrink-0">
              <div className="portrait-inner">
                <span className="text-7xl">✿</span>
                <span className="absolute bottom-5 right-5 rotate-12 font-hand text-xl text-rose">that&apos;s me!</span>
              </div>
            </div>
            <div className="flex-1 space-y-6">
              <p className="font-hand text-2xl text-rose">A gentle mind with a curious heart.</p>
              <p className="text-lg leading-8 text-ink/70">
                I&apos;m a <strong className="font-semibold text-ink">final year Software Engineering student</strong> at
                Universiti Tenaga Nasional who loves turning ideas into welcoming, useful spaces on the web.
                When I&apos;m not coding, you&apos;ll find me collecting inspiration, making playlists, or chasing good light.
              </p>
              <div className="flex flex-wrap gap-3 pt-2 text-sm">
                <span className="soft-pill soft-pill-rose">♡ Kuala Lumpur, Malaysia</span>
                <span className="soft-pill soft-pill-lavender">✦ Open to opportunities</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

export function Skills() {
  return (
    <section id="skills" className="relative z-10 bg-white/30 px-4 py-24 md:py-32">
      <div className="reveal mx-auto max-w-5xl">
        <SectionHeading number="02." tone="lavender" reversed>Things I love</SectionHeading>
        <div className="grid grid-cols-2 gap-4 md:grid-cols-3 md:gap-6">
          {skills.map(([icon, name, alternate]) => (
            <div key={name} className={`skill-node ${alternate ? "alt-glow" : ""}`}>
              <span className="skill-icon">{icon}</span><span>{name}</span>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export function Experience() {
  return (
    <section id="experience" className="relative z-10 px-4 py-24 md:py-32">
      <div className="reveal mx-auto max-w-5xl">
        <SectionHeading number="03." tone="lavender" reversed>My story so far</SectionHeading>
        <div className="glass-card story-card rounded-[2rem] p-7 md:p-12">
          <p className="font-display text-sm uppercase tracking-[0.2em] text-rose">2021 — Present</p>
          <div>
            <h3 className="mt-4 font-display text-2xl text-ink md:text-3xl">Learning, building &amp; becoming</h3>
            <p className="mt-4 max-w-2xl text-base leading-8 text-ink/65">
              From my first lines of code to shipping real projects, I&apos;ve been learning how
              thoughtful technology can make everyday life feel a little easier. My work sits at
              the intersection of reliable engineering and beautiful, human details.
            </p>
          </div>
          <span className="story-star" aria-hidden="true">✦</span>
        </div>
      </div>
    </section>
  );
}

export function Projects() {
  return (
    <section id="projects" className="relative z-10 px-4 py-24 md:py-32">
      <div className="reveal mx-auto max-w-6xl">
        <SectionHeading number="04.">A few favourites</SectionHeading>
        <div className="grid gap-8 md:grid-cols-2">
          {projects.map((project) => (
            <article key={project.title} className={`project-card ${project.tone === "lavender" ? "project-card-lavender" : ""}`}>
              <div className="project-image">
                <Image src={project.image} alt={project.title} width={800} height={520} unoptimized />
                <span className="image-sparkle">✦</span>
              </div>
              <div className="flex flex-1 flex-col">
                <span className="mb-3 text-xs font-semibold uppercase tracking-[0.2em] text-rose">{project.label}</span>
                <h3 className="font-display text-3xl text-ink">{project.title}</h3>
                <p className="mb-7 mt-4 flex-1 leading-7 text-ink/65">{project.description}</p>
                <a href="#projects" className="project-link">See the case study <span>↗</span></a>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}
